import{_ as o,o as t,c as s,a5 as d}from"./chunks/framework.BvXk9IVy.js";const h=JSON.parse('{"title":"用 VitePress 搭一间自己的书斋","description":"","frontmatter":{"title":"用 VitePress 搭一间自己的书斋"},"headers":[],"relativePath":"notes/build-with-vitepress.md","filePath":"notes/build-with-vitepress.md","lastUpdated":1791895356000}'),i={name:"notes/build-with-vitepress.md"};function r(c,e,n,p,a,l){return t(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="用-vitepress-搭一间自己的书斋" tabindex="-1">用 VitePress 搭一间自己的书斋</h1><blockquote><p>盖房子之前先想清楚要住多久，比选哪种砖更要紧。</p></blockquote><p>上一篇里说过，上一间书斋停在三年前。这次重新动手，第一件事不是挑主题，是想明白上次为什么塌。</p><h2 id="上一间是怎么塌的" tabindex="-1">上一间是怎么塌的</h2><p>旧站用的是 Hexo。它没有错，只是对我来说太重了：一次大版本升级之后，主题的模板语法跟着变了；本地 Node 的版本卡在某个区间里；换台机器就要重新配一遍环境。真正压垮它的是一件很小的事——某天我只想改一个错别字，结果花了四十分钟在装依赖。</p><p>一间书斋如果进门要先搬开一堆家具，那它迟早会被空着。</p><h2 id="为什么是-vitepress" tabindex="-1">为什么是 VitePress</h2><ul><li><strong>Hexo</strong>：生态老，插件多，但模板层和 Markdown 是两套语法，改版式等于改主题代码。我不想再学一遍主题怎么写。</li><li><strong>Hugo</strong>：构建是真的快，Go 模板也是真的难读。我要改一处布局，得先回忆半天它的上下文变量从哪来。</li><li><strong>Nextra</strong>：走的是 React 那一套，灵活，但对我来说是杀鸡用牛刀。为了写几百字，去维护一整个 Next 项目，不值。</li><li><strong>VitePress</strong>：Markdown 是唯一的事实来源，构建交给 Vite，主题就是 Vue 组件。写文章和改版式用的是同一门手艺，这就够了。</li></ul><p><code>vitepress</code> 锁在 <code>1.6.4</code>。版本写死不是保守，是知道自己不会天天跟着升级走。</p><h2 id="markdown-是源-不是格式" tabindex="-1">Markdown 是源，不是格式</h2><p>这一点的好处要写过才体会得到。文章就是 <code>docs</code> 下面一个个 <code>.md</code> 文件，标题是 <code>#</code>，分段是空行，链接是方括号加圆括号。没有数据库，没有后台，没有「导出」这个动作。</p><p>想找三年前写过什么，直接翻文件夹。想改，打开编辑器。哪天不想用 VitePress 了，把 <code>docs</code> 打包带走，换任何工具都能读。</p><p>至于产物，<code>npm run build</code> 之后全在 <code>docs/.vitepress/dist</code> 里，是一堆静态 HTML、CSS 和 JS。GitHub Actions 那边也是把这个目录原样上传成 Pages 的产物，不需要额外的发布步骤。</p><h2 id="三件我不要的东西" tabindex="-1">三件我不要的东西</h2><ul><li><strong>不要评论</strong>。评论区是给人看的，但更多时候是给情绪看的。没有人留言，不代表没有人读过。</li><li><strong>不要统计</strong>。一旦能看到阅读量，就会忍不住去看，然后开始按数字写东西。</li><li><strong>不要广告</strong>。理由不必解释。</li></ul><p>这三条听起来像是姿态，其实只是为了让这间书斋安静。安静是它可以被长期住下去的唯一条件。</p><h2 id="一处顺手留下的缺口" tabindex="-1">一处顺手留下的缺口</h2><p><code>base</code> 写的是 <code>/Blog-pages/</code>，因为部署地址是 <code>yichen0808.github.io/Blog-pages/</code>。注意这里大小写不能改：GitHub Pages 的项目站点路径就是仓库名本身，而路径是大小写敏感的——写成小写的 <code>blog_pages</code> 之后首页照样打得开（<code>index.html</code> 由 Pages 直接给出），但所有 CSS、JS 和图片会一起 404。等哪天绑上自己的域名，把它改成 <code>/</code> 就行。</p><p>配置里还有一行 <code>ignoreDeadLinks: true</code>。那是我为了让站点先跑起来，对一批还没写的文章做的妥协。写完它们之后，这一行应该改回 <code>false</code>——让死链检查重新开始干活，比我自己记得哪些链接没写要可靠。</p><h2 id="小结" tabindex="-1">小结</h2><p>框架选型到头来不复杂：挑一个「不想写的时候也能写」的。VitePress 对我来说就是那个——起一个 dev 服务器几秒钟的事，写不写是一回事，门槛先拆掉。</p>',21)])])}const u=o(i,[["render",r]]);export{h as __pageData,u as default};
